function selectDoctrine(id){const d=DOCTRINES[id];if(!d||state.doctrines[id])return;state.doctrines[id]=true;d.apply();state.doctrinePicks++;save.stats.doctrinesChosen++;AUDIO.sfx('doctrine');flashWrap();toast(`DOCTRINE — ${d.name}`,d.desc);hide('doctrineScreen');state.choosing=false;state.choiceMode='';state.paused=false;state.last=performance.now();if(state.doctrinePicks>=2)unlockAchievement('doctrine');if(state.pendingLevelAfterDoctrine){state.pendingLevelAfterDoctrine=false;openLevel()}else processCeremony()}


