function addWeapon(id,level=1){state.weapons[id]={level,evolved:false,overcharge:0,timer:0,aux:0};discoverWeapon(id)}
function weaponLevelDesc(id,l){const t={pulse:['+18% damage','+1 projectile','-14% cooldown','+1 pierce','+22% damage'],missile:['+22% damage','+1 missile','-16% cooldown','+30% blast','+1 missile'],drone:['+1 drone','+18% damage','-16% cooldown','+1 drone','+25% damage'],arc:['+1 chain','+18% damage','-16% cooldown','+1 chain','+25% range'],rail:['+1 pierce','+24% damage','-16% cooldown','+1 projectile','+2 pierce'],nova:['+18% radius','+22% damage','-16% cooldown','double pulse','+24% damage'],mine:['+1 active mine','+25% damage','-16% cooldown','+22% radius','+1 active mine'],beam:['+1 pierce','+20% damage','-16% cooldown','+1 beam','+28% damage'],flak:['+2 fragments','+18% damage','-14% cooldown','+20% range','+2 fragments'],blade:['+1 blade','+18% damage','-14% tick rate','+18% orbit radius','+1 blade'],rift:['+18% radius','+18% damage','-14% cooldown','+25% duration','+20% pull']};return t[id]?.[Math.max(0,l-2)]||'Maximum level'}
