  state={mode:'run',diff,contract,sector,sectorId:save.sector,contractId:save.contract,difficulty:save.difficulty,time:0,last:now,paused:false,choosing:false,choiceMode:'',ceremony:false,ceremonyQueue:[],gameOver:false,victory:false,clearedBase:false,endless:false,ascension:0,nextEndlessBoss:0,revived:false,finalizing:false,runCredits:0,kills:0,score:0,spawnT:0,eliteT:36,bossStage:0,level:1,xp:0,xpNeed:8,rerolls:1+(save.research.reroll||0)+(mastery>=4?1:0),skips:1+(mastery>=2?1:0),currentOffers:[],runCounted:false,accountedKills:0,accountedCredits:0,threat:1,chain:0,chainBest:0,chainTimer:0,rush:0,rushActivations:0,rushKills:0,rushBest:0,nextBounty:65,bounty:null,nextAnomaly:115,nextSecret:(145+Math.random()*45)/(sector.secret||1),nextNemesis:350,nemesisKilled:0,redline:false,overdrive:0,driveTier:0,grazeChain:0,grazeBest:0,grazeTimer:0,grazes:0,cachesOpened:0,conversions:0,evolutions:0,doctrines:{},doctrinePicks:0,pendingLevelAfterDoctrine:false,damageDealt:0,damageTaken:0,bossesKilled:0,flawlessBosses:0,secretEvents:0,weaponDamage:{},noHit:true,newUnlocks:[],protocols:{},artifacts:{},synergies:{},hitStop:0,critFxCooldown:0,surgeUntil:0,p,passives:{},weapons:{},enemies:[],bullets:[],enemyBullets:[],orbs:[],caches:[],mines:[],rifts:[],allies:[],particles:[],floaters:[],arcs:[],beams:[],shake:0,stars:Array.from({length:110},()=>({x:Math.random()*W,y:Math.random()*H,z:1+Math.random()*2,phase:Math.random()*Math.PI*2}))};
