  const input=moveInput();let dx=input.dx,dy=input.dy;p.moving=!!(dx||dy);if(dx||dy){const l=Math.hypot(dx,dy),nx=dx/l,ny=dy/l,driveSpeed=[1,1.08,1.12,1.16,1.20][state.driveTier]||1;p._lastMoveX=nx;p._lastMoveY=ny;p.x+=nx*p.speed*driveSpeed*dt;p.y+=ny*p.speed*driveSpeed*dt}p.x=clamp(p.x,14,W-14);p.y=clamp(p.y,14,H-14);
