  for(const b of state.bullets){if(b.life<=0)continue;for(const e of state.enemies){if(e.dead)continue;if(dist2(b,e)<(b.r+e.r)*(b.r+e.r)){damageEnemy(e,b.damage,true,b.weaponId);if(b.blast>0){for(const x of state.enemies)if(!x.dead&&x!==e&&dist2(e,x)<b.blast*b.blast)damageEnemy(x,b.damage*.42,false,b.weaponId);if(b.weaponId==='missile'&&state.synergies.fragmentation){for(let i=0;i<5;i++){const aa=i/5*Math.PI*2;state.bullets.push({x:e.x,y:e.y,vx:Math.cos(aa)*360,vy:Math.sin(aa)*360,r:2,life:.38,damage:b.damage*.18,pierce:0,homing:0,blast:0,color:'#ffd27a',weaponId:'fragmentation'})}}}if(b.pierce>0)b.pierce--;else{b.life=0;break}}}}
  for(const m of state.mines){m.life-=dt;let target=null;for(const e of state.enemies){if(!e.dead&&dist2(m,e)<45*45){target=e;break}}if(target){m.life=0;AUDIO.sfx('mine');addShake(state.synergies.gravityPulse?5:3);state.arcs.push({circle:true,x1:m.x,y1:m.y,r:m.blast,life:.12,color:'#bd9cff'});for(const e of state.enemies)if(!e.dead&&dist2(m,e)<m.blast*m.blast)damageEnemy(e,critDamage(m.damage),false,'mine');if(state.synergies.gravityPulse){const r=m.blast*1.5;state.arcs.push({circle:true,x1:m.x,y1:m.y,r,life:.18,color:'#ffffff'});for(const e of state.enemies)if(!e.dead&&dist2(m,e)<r*r)damageEnemy(e,m.damage*.34,false,'gravity-pulse',false)}}}
  for(const b of state.enemyBullets){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;const d2=dist2(b,p);if(d2<(b.r+p.r)*(b.r+p.r)){b.life=0;hitPlayer(b.damage)}else if(!b.grazed&&d2<(b.r+p.r+p.grazeRadius)*(b.r+p.r+p.grazeRadius)){b.grazed=true;state.grazes++;state.grazeChain=state.grazeTimer>0?state.grazeChain+1:1;state.grazeTimer=1.15;state.grazeBest=Math.max(state.grazeBest,state.grazeChain);const gMul=1+Math.min(2,state.grazeChain*.08);state.score+=14*gMul*state.p.scoreMul*state.diff.score*(state.contract?.score||1);state.chainTimer=Math.max(state.chainTimer,.65);AUDIO.sfx('graze');if(p.frame==='specter'){state.driveTier=Math.max(state.driveTier,1);state.overdrive=Math.max(state.overdrive,.35)}const milestone=state.grazeChain===3?1:state.grazeChain===7?2:state.grazeChain===12?3:0;if(milestone){AUDIO.sfx('grazeTier',milestone);message(milestone===1?'CLOSE':milestone===2?'DANGER':'INSANE GRAZE',420)}if(state.p.grazeOverclock&&state.grazeChain>=5)for(const w of Object.values(state.weapons))w.timer=Math.max(0,w.timer-.10);if(state.grazes>=25)unlockAchievement('graze_25')}}
  for(const o of state.orbs){const d=Math.hypot(p.x-o.x,p.y-o.y),magnet=p.magnet*(state.rush>0?1.85:1);if(d<magnet){const sp=(state.rush>0?230:135)+(magnet-d)*4;o.x+=(p.x-o.x)/Math.max(1,d)*sp*dt;o.y+=(p.y-o.y)/Math.max(1,d)*sp*dt}if(d<p.r+o.r+5){o.dead=true;AUDIO.sfx('pickup');gainXp(o.val)}}
  for(const c of state.caches){c.life-=dt;const d=Math.hypot(p.x-c.x,p.y-c.y);if(d<p.magnet*1.3){const sp=105+(p.magnet-d)*3;c.x+=(p.x-c.x)/Math.max(1,d)*sp*dt;c.y+=(p.y-c.y)/Math.max(1,d)*sp*dt}if(d<p.r+c.r+7)openCache(c)}
  for(const a of state.allies){a.life-=dt;if(a.life<=0&&!a.expired){a.expired=true;if(state.p.allyExplosion>0){const r=65+state.p.allyExplosion*20,damage=30*state.p.damageMul*state.p.allyExplosion;AUDIO.sfx('nova');state.arcs.push({circle:true,x1:a.x,y1:a.y,r,life:.16,color:'#8dffd6'});for(const e of state.enemies)if(!e.dead&&dist2(a,e)<r*r)damageEnemy(e,damage,false,'scuttle',false)}}const target=nearest(a);if(target){const ang=Math.atan2(target.y-a.y,target.x-a.x);a.x+=Math.cos(ang)*(a.type==='charger'?72:48)*dt;a.y+=Math.sin(ang)*(a.type==='charger'?72:48)*dt}a.fireT-=dt;if(a.fireT<=0){a.fireT=(a.baseFire||.72)/state.p.allyFireMul;allyShoot(a)}}
