  if(kind==='supernova'){
    const x=RENDER_W*.925,y=RENDER_H*.46,pulse=.70+.30*Math.sin(t*2.25),wave=(t*56)%(RENDER_W*.28);
    celestialG.fillStyle(0xffd38a,.032+.022*pulse).fillCircle(x,y,92+16*pulse);celestialG.fillStyle(0xb8efff,.025+.015*pulse).fillCircle(x,y,58+9*pulse);
    celestialG.lineStyle(4,0xffd89a,.12*(1-wave/(RENDER_W*.28))).strokeCircle(x,y,64+wave);celestialG.lineStyle(2,0x8de9ff,.10*(1-wave/(RENDER_W*.28))).strokeCircle(x,y,82+wave*1.18);
  }else if(kind==='rift'){
    const x=RENDER_W*.15,y=RENDER_H*.43;for(let i=0;i<5;i++){const wobble=Math.sin(t*1.4+i)*7;celestialG.lineStyle(2+i*.45,i%2?0x7b63ff:0x9edcff,.045+i*.018).strokeEllipse(x,y,176+i*25+wobble,118+i*17-wobble*.5)}
    celestialG.fillStyle(0x7158ff,.025+.015*Math.sin(t*1.7)).fillCircle(x,y,105);
  }else if(kind==='pulsar'){
    const x=RENDER_W*.50,y=RENDER_H*.075,a=.05+.035*(.5+.5*Math.sin(t*3.8));celestialG.fillStyle(0xd9fbff,.18).fillCircle(x,y,5+Math.sin(t*4)*1.5);
    celestialG.lineStyle(3,0x7be9ff,a).beginPath().moveTo(x,y).lineTo(RENDER_W*.08,RENDER_H*.57).strokePath();celestialG.lineStyle(3,0x7be9ff,a).beginPath().moveTo(x,y).lineTo(RENDER_W*.92,RENDER_H*.57).strokePath();
  }
